    int totalPoints;
    cin >> totalPoints;
    if (totalPoints >= 100) {
        cout << 0 << "\n";
    } else {
        vector<int> coords1(totalPoints + 1), coords2(totalPoints + 1), coords3(totalPoints + 1), coords4(totalPoints + 1), coords5(totalPoints + 1);
        for (int i = 1; i <= totalPoints; i++) {
            cin >> coords1[i] >> coords2[i] >> coords3[i] >> coords4[i] >> coords5[i];
        }
        std::unordered_set<int> invalid;
        for (int i = 1; i <= totalPoints; i++) {
            for (int j = 1; j <= totalPoints; j++) {
                for (int k = 1; k <= totalPoints; k++) {
                    if (i == j || j == k || k == i) continue;
                    long long diffA = coords1[j] - coords1[i];
                    long long diffB = coords2[j] - coords2[i];
                    long long diffC = coords3[j] - coords3[i];
                    long long diffD = coords4[j] - coords4[i];
                    long long diffE = coords5[j] - coords5[i];

                    long long diffA2 = coords1[k] - coords1[i];
                    long long diffB2 = coords2[k] - coords2[i];
                    long long diffC2 = coords3[k] - coords3[i];
                    long long diffD2 = coords4[k] - coords4[i];
                    long long diffE2 = coords5[k] - coords5[i];

                    double dotProduct = diffA * diffA2 + diffB * diffB2 + diffC * diffC2 + diffD * diffD2 + diffE * diffE2;
                    long long mag1 = diffA * diffA + diffB * diffB + diffC * diffC + diffD * diffD + diffE * diffE;
                    long long mag2 = diffA2 * diffA2 + diffB2 * diffB2 + diffC2 * diffC2 + diffD2 * diffD2 + diffE2 * diffE2;

                    double cosine = 0.0;
                    if (mag1 != 0 && mag2 != 0) {
                        cosine = dotProduct / (sqrt((double)mag1) * sqrt((double)mag2));
                        // Clamp cosine to [-1,1] to avoid floating point errors
                        if (cosine > 1.0) cosine = 1.0;
                        if (cosine < -1.0) cosine = -1.0;
                    }
                    double angleDeg = acos(cosine) * 180.0 / M_PI;
                    if (angleDeg + 1e-9 < 90.0) {
                        invalid.insert(i);
                    }
                }
            }
        }
        cout << totalPoints - (int)invalid.size() << "\n";
        for (int i = 1; i <= totalPoints; i++) {
            if (invalid.find(i) == invalid.end()) {
                cout << i << "\n";
            }
        }
    }
    return 0;
}
